import { JSDOM } from "jsdom";
import fs from "node:fs";

const dom = new JSDOM(`<!DOCTYPE html><div id="root"></div>`, { runScripts: "outside-only", pretendToBeVisual: true });
const { window } = dom;
global.window = window; global.document = window.document; global.navigator = window.navigator;
global.IS_REACT_ACT_ENVIRONMENT = true;

// Load React UMD into jsdom
function loadScript(path){
  const code = fs.readFileSync(path, "utf8");
  window.eval(code);
}
loadScript("./node_modules/react/umd/react.development.js");
loadScript("./node_modules/react-dom/umd/react-dom.development.js");

const React = window.React; const ReactDOM = window.ReactDOM;
const e = React.createElement;
let setImp;

function App(){
  const [imp,setImpState] = React.useState(8.5);
  setImp = setImpState;
  return e("div",null,
    e("label",{htmlFor:"i"},"Importance: "+imp.toFixed(1)),
    e("input",{id:"i",type:"range",min:1,max:10,step:0.1,value:imp,onChange:ev=>setImpState(Number(ev.target.value))}),
    e("span",{id:"out"},"imp="+imp.toFixed(1))
  );
}
ReactDOM.createRoot(document.getElementById("root")).render(e(App));
await new Promise(r=>setTimeout(r,100));

const input = document.getElementById("i");
const out = document.getElementById("out");
console.log("INITIAL:", out.textContent);

// --- Replicate Playwright fill() for range inputs exactly ---
// Playwright source: e.focus(); e.value = t; dispatchEvent(new Event('input')); dispatchEvent(new Event('change'))
input.focus();
input.value = "9.2";
input.dispatchEvent(new window.Event("input", { bubbles: true, composed: true }));
input.dispatchEvent(new window.Event("change", { bubbles: true }));
await new Promise(r=>setTimeout(r,100));
console.log("AFTER playwright-fill-sequence:", out.textContent, "| dom value:", input.value);
EOF
