+          <input
+            type="text"
+            className="studio-input"
+            placeholder="Search opportunities / outcomes by statement or ID..."
+            value={searchQuery}
+            onChange={(e) => setSearchQuery(e.target.value)}
+            style={{ width: "100%" }}
+          />
