+  onHoverOutcome: (outcome: Outcome | null) => void;
+  activeOutcome: Outcome | null;
+}
+
+function OpportunityMatrixView({
+  outcomes,
+  selectedOutcomeId,
+  onSelectOutcome,
+  onHoverOutcome,
+  activeOutcome,
+}: MatrixViewProps) {
+  return (
+    <div style={{ display: "grid", gridTemplateColumns: "1fr 320px", gap: 16 }}>
+      {/* Interactive 2D Chart */}
+      <div
+        style={{
