+                  {outcome.statement}
+                </td>
+                <td style={{ padding: "10px 14px", textAlign: "right", fontWeight: 600 }}>
+                  {outcome.importance ?? "—"}
+                </td>
+                <td style={{ padding: "10px 14px", textAlign: "right", fontWeight: 600 }}>
+                  {outcome.satisfaction ?? "—"}
+                </td>
+                <td
+                  style={{
+                    padding: "10px 14px",
+                    textAlign: "right",
+                    fontWeight: 800,
+                    color: underserved ? "var(--studio-amber)" : "inherit",
+                  }}
+                >
+                  {opp.toFixed(1)}
+                </td>
+                <td style={{ padding: "10px 14px", textAlign: "center" }}>
+                  <span
+                    className="studio-pill"
