+                      background: underserved ? "rgba(251, 191, 36, 0.15)" : "rgba(255,255,255,0.05)",
+                      color: underserved ? "var(--studio-amber)" : "var(--studio-muted)",
+                      fontSize: "0.72rem",
+                    }}
+                  >
+                    {underserved ? "UNDERSERVED" : "NORMAL"}
+                  </span>
+                </td>
+              </tr>
+            );
+          })}
+        </tbody>
+      </table>
+    </div>
