+    void boot();
+    return () => {
+      cancelled = true;
+    };
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, []);
+
+  const value = useMemo<StudioContextValue>(
+    () => ({
+      settings,
+      saveSettings,
+      displayName,
+      setDisplayName,
+      brief,
+      saveBrief,
+      setupOpen,
+      openSetup,
+      closeSetup,
+      canvas,
+      canvasLoading,
+      canvasCached,
+      refreshCanvas,
+      llmHealth,
+      mcpReachable,
+      sidecarReachable,
