+      offlineReply,
+      addStep,
+      addOutcome,
+      createJob,
+      updateJob,
+      deleteJob,
+      updateStep,
+      deleteStep,
+      updateOutcome,
+      deleteOutcome,
+      activePanel,
+      openPanel,
+      closePanel,
+      ask,
+      toasts,
+      pushToast,
+      dismissToast,
+      connectors,
+      presets,
+      refreshConnectors,
+      refreshPresets,
+      addConnector,
+      deleteConnector,
+      connectorSuggestions,
+      dismissConnectorSuggestion,
+      notifications,
+      unreadNotificationCount,
+      markNotificationAsRead,
+      markAllNotificationsAsRead,
+      dismissNotification,
+      addNotification,
+      simulateBackgroundEvent,
+    }),
+    [
+      settings,
+      saveSettings,
+      displayName,
+      setDisplayName,
+      brief,
+      saveBrief,
+      setupOpen,
+      openSetup,
+      closeSetup,
+      canvas,
+      canvasLoading,
+      canvasCached,
+      refreshCanvas,
+      llmHealth,
+      mcpReachable,
+      sidecarReachable,
+      checkConnections,
+      messages,
+      streaming,
+      thinkingPhase,
+      toolActivity,
+      sendMessage,
+      stopStreaming,
+      clearChat,
+      pushNotice,
+      offlineReply,
+      addStep,
+      addOutcome,
+      createJob,
+      updateJob,
+      deleteJob,
+      updateStep,
+      deleteStep,
+      updateOutcome,
+      deleteOutcome,
+      activePanel,
+      openPanel,
+      closePanel,
+      ask,
+      toasts,
+      pushToast,
+      dismissToast,
+      connectors,
+      presets,
+      refreshConnectors,
+      refreshPresets,
+      addConnector,
+      deleteConnector,
+      connectorSuggestions,
+      dismissConnectorSuggestion,
+      notifications,
+      unreadNotificationCount,
+      markNotificationAsRead,
+      markAllNotificationsAsRead,
+      dismissNotification,
+      addNotification,
+      simulateBackgroundEvent,
+    ],
+  );
+
+  return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
+}
+
+export function useStudio(): StudioContextValue {
+  const context = useContext(StudioContext);
+  if (!context) {
+    throw new Error("useStudio must be used within a StudioProvider");
+  }
+  return context;
+}

