+/* ------------------------------------------------------------------ */
+/* Rail: what the thread has made, above the thread                   */
+/* ------------------------------------------------------------------ */
+.rail {
+  flex: none;
+  padding: 0 22px;
+}
+
+.rail__list {
+  display: flex;
+  align-items: center;
+  gap: 2px;
+  width: 100%;
